I was thinking something along the following lines:
```C#
static IEnumerable<T> Shuffle<T>(IList<T> source)
{
    int n = source.Count;
    int[] permutationMap = ArrayPool<int>.Shared.Rent(n);
    PopulatePermutationMap(permutationMap.AsSpan(0, n));

    try
    {
        for (int i = 0; i < n; i++)
        {
            yield return source[permutationMap[i]];
        }
    }
    finally
    {
        ArrayPool<int>.Shared.Return(permutationMap);
    }
}

static void PopulatePermutationMap(Span<int> span)
{
    Random random = Random.Shared;

    int i = 0;
    for (; i <= span.Length - 4; i += 4)
    {
        span[i] = i;
        span[i + 1] = i + 1;
        span[i + 2] = i + 2;
        span[i + 3] = i + 3;
    }
    for (; i < span.Length; i++)
    {
        span[i] = i;
    }

    for (i = 0; i < span.Length - 1; i++)
    {
        int j = random.Next(i, span.Length);
        if (i != j)
        {
            int temp = span[i];
            span[i] = span[j];
            span[j] = temp;
        }
    }
}
```
